cypress_script:
describe('Contact Form Validation', () => {
  it('should submit the form successfully with valid data', () => {
    cy.visit('https://practicesoftwaretesting.com/contact');
    cy.get('#first_name').type('John');
    cy.get('#last_name').type('Doe');
    cy.get('#email').type('john.doe@example.com');
    cy.get('#message').type('This is a test message.');
    cy.get('select[data-test="subject"]').select('Customer service');
    cy.get('input[data-test="contact-submit"]').click();
    cy.url().should('eq', 'https://practicesoftwaretesting.com/contact');
  });

  it('should show validation errors when required fields are empty', () => {
    cy.visit('https://practicesoftwaretesting.com/contact');
    cy.get('input[data-test="contact-submit"]').click();
    cy.get('#first_name').should('be.visible');
    cy.get('#last_name').should('be.visible');
    cy.get('#email').should('be.visible');
    cy.get('#message').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Contact Form Validation', () => {
  test('should submit the form successfully with valid data', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/contact');
    await page.fill('#first_name', 'John');
    await page.fill('#last_name', 'Doe');
    await page.fill('#email', 'john.doe@example.com');
    await page.fill('#message', 'This is a test message.');
    await page.selectOption('select[data-test="subject"]', 'customer-service');
    await page.click('input[data-test="contact-submit"]');
    await expect(page).toHaveURL('https://practicesoftwaretesting.com/contact');
  });

  test('should show validation errors when required fields are empty', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/contact');
    await page.click('input[data-test="contact-submit"]');
    const firstName = page.locator('#first_name');
    const lastName = page.locator('#last_name');
    const email = page.locator('#email');
    const message = page.locator('#message');
    await expect(firstName).toBeVisible();
    await expect(lastName).toBeVisible();
    await expect(email).toBeVisible();
    await expect(message).toBeVisible();
  });
});
